function rotateOptions<T>(items: T[], seed: number): T[] {
  const shift = seed % items.length;
  return items.slice(shift).concat(items.slice(0, shift));
}

function buildEscapeOptions(clue: EscapeClueSeed, safeNext: string, seed: number) {
  const options = [
    { label: clue.answer, nextNode: safeNext, isSafe: true },
    { label: clue.distractors[0], nextNode: `dead-${seed}-a`, isSafe: false },
    { label: clue.distractors[1], nextNode: `dead-${seed}-b`, isSafe: false },
  ];
  return rotateOptions(options, seed);
}

